metadata.preview:
{
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start"
  },
  "dependencies": {
    "next": "^16.4.0-canary.26",
    "react": "19.1.0",
    "react-dom": "19.1.0"
  },
  "devDependencies": {
    "@types/node": "^20",
    "@types/react": "^19",
    "@types/react-dom": "^19",
    "@vitejs/plugin-react": "^4.4.1",
    "typescript": "^5",
    "vite-tsconfig-paths": "^5.1.4",

import Link from 'next/link'

export default function Home() {
  return (
    <main>
      <h1>Featured product</h1>
      <Link href="/product">View Premium Widget</Link>
    </main>
  )
}

import { getRelatedProducts } from '@/lib/data'

export default async function ProductPage() {
  const relatedProducts = await getRelatedProducts()

  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      <section>
        <h2>Related products</h2>
        <ul>
          {relatedProducts.map((product) => (
            <li key={product}>{product}</li>
          ))}
        </ul>
      </section>
    </main>
  )
}

import { cacheLife } from 'next/cache'

export async function getRelatedProducts() {
  'use cache'
  cacheLife('hours')
  return ['Compact Widget', 'Widget Carry Case']
}

import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Featured product',
  description: 'Shop our featured product',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

